import { z } from "zod";

import { hasDuplicateClinicalCode } from "@/components/Questionnaire/QuestionTypes/conditionValidation";
import type { ResolvedStructuredType } from "@/components/QuestionnaireV2/structured/registry";

import { CodeSchema } from "@/types/base/code/code";
import {
  DIAGNOSIS_CATEGORY,
  DIAGNOSIS_CLINICAL_STATUS,
  DIAGNOSIS_SEVERITY,
  DIAGNOSIS_VERIFICATION_STATUS,
} from "@/types/emr/diagnosis/diagnosis";
import type {
  QuestionnaireResponse,
  ResponseValue,
} from "@/types/questionnaire/form";
import type { Question } from "@/types/questionnaire/question";

import { structuredRecordSchemas } from "./structuredRecordSchema";
import type { FillSubject } from "./subject";

const clinicalCodeSchema = CodeSchema.extend({
  code: z.string().trim().min(1),
  system: z.string().trim().min(1),
  display: z.string().trim().min(1),
});
const clinicalRecordSchema = z
  .object({
    id: z.string().min(1).optional(),
    code: clinicalCodeSchema,
    clinical_status: z.enum(DIAGNOSIS_CLINICAL_STATUS),
    verification_status: z.enum(DIAGNOSIS_VERIFICATION_STATUS),
    severity: z.enum(DIAGNOSIS_SEVERITY).nullable(),
    category: z.string().min(1),
    note: z
      .string()
      .nullish()
      .transform((note) => note ?? undefined),
    onset: z
      .looseObject({
        onset_datetime: z.string().optional(),
        onset_age: z.string().optional(),
        onset_string: z.string().optional(),
        note: z.string().optional(),
      })
      .optional(),
    recorded_date: z.string().optional(),
  })
  .loose();

type StructuredFillResult =
  { ok: true; value: ResponseValue } | { ok: false; error: string };

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

/** Structured answers carry one array of domain records, regardless of
 *  the questionnaire's primitive-answer repeats setting. */
export function coerceStructuredFillValue(
  question: Question,
  rawValues: unknown[],
  current: QuestionnaireResponse,
  definition: ResolvedStructuredType,
  subject: FillSubject,
): StructuredFillResult {
  const type = question.structured_type;
  const fail = (error: string): StructuredFillResult => ({ ok: false, error });
  if (!type || type === "files" || definition.draftPolicy === "exclude") {
    return fail(
      `Question "${question.link_id}" cannot be filled with JSON records`,
    );
  }
  if (
    ["encounter", "appointment", "time_of_death"].includes(type) &&
    rawValues.length > 1
  ) {
    return fail(
      `Question "${question.link_id}" accepts at most one ${type} record`,
    );
  }

  let data: unknown[] = [];
  if (type === "time_of_death") {
    const parsed = z
      .array(z.iso.datetime({ offset: true }))
      .safeParse(rawValues);
    if (!parsed.success)
      return fail("Time of death must be an ISO datetime with a timezone");
    data = parsed.data;
  } else {
    if (!rawValues.every(isRecord))
      return fail(`${type} values must be JSON objects`);
    data = rawValues.map((raw) => {
      const row = { ...raw };
      if (
        "patientId" in subject &&
        ("patient" in row || type === "charge_item")
      ) {
        row.patient = subject.patientId;
      }
      if (
        subject.type === "encounter" &&
        ("encounter" in row ||
          [
            "diagnosis",
            "symptom",
            "medication_request",
            "service_request",
            "charge_item",
          ].includes(type))
      ) {
        row.encounter = subject.encounterId;
      }
      if (type === "service_request" && isRecord(row.service_request)) {
        const nested = { ...row.service_request };
        if ("patient" in nested && "patientId" in subject)
          nested.patient = subject.patientId;
        if ("encounter" in nested && subject.type === "encounter")
          nested.encounter = subject.encounterId;
        row.service_request = nested;
      }
      if (type === "diagnosis" || type === "medication_request")
        row.dirty = true;
      return row;
    });
  }

  if (type === "diagnosis" || type === "symptom") {
    const schema = clinicalRecordSchema.extend({
      category:
        type === "diagnosis" ? z.enum(DIAGNOSIS_CATEGORY) : z.string().min(1),
      severity:
        type === "diagnosis"
          ? z.enum(DIAGNOSIS_SEVERITY).nullable()
          : z.enum(DIAGNOSIS_SEVERITY),
    });
    const parsed = z.array(schema).safeParse(data);
    if (!parsed.success) {
      return fail(
        `Invalid ${type} record: ${parsed.error.issues.map((issue) => `${issue.path.join(".")}: ${issue.message}`).join("; ")}`,
      );
    }
    const currentRows: unknown = current.values[0]?.value;
    const existing = (Array.isArray(currentRows) ? currentRows : []).filter(
      (
        row,
      ): row is {
        id: string;
        code: { code: string };
        verification_status: string;
      } =>
        isRecord(row) &&
        typeof row.id === "string" &&
        !!row.id &&
        isRecord(row.code) &&
        typeof row.code.code === "string" &&
        typeof row.verification_status === "string",
    );
    const seen: z.infer<typeof clinicalRecordSchema>[] = [];
    const ids = new Set<string>();
    const updatedIds = new Set(
      parsed.data.map((row) => row.id).filter(Boolean),
    );
    const unchanged = existing.filter((entry) => !updatedIds.has(entry.id));
    for (const row of parsed.data) {
      if (row.id && ids.has(row.id))
        return fail(`Duplicate ${type} record id "${row.id}"`);
      if (row.id) ids.add(row.id);
      if (
        row.verification_status !== "entered_in_error" &&
        (hasDuplicateClinicalCode(seen, row.code.code) ||
          hasDuplicateClinicalCode(unchanged, row.code.code))
      ) {
        return fail(`Duplicate ${type} code "${row.code.code}"`);
      }
      seen.push(row);
    }
    data = parsed.data;
  }

  const recordSchema = structuredRecordSchemas[type];
  if (recordSchema) {
    const parsed = z.array(recordSchema).safeParse(data);
    if (!parsed.success) {
      return fail(
        `Invalid ${type} record: ${parsed.error.issues.map((issue) => `${issue.path.join(".")}: ${issue.message}`).join("; ")}`,
      );
    }
    data = parsed.data;
  }

  try {
    const errors =
      definition.validate?.(data, question.id, !!question.required) ?? [];
    if (errors.length) {
      return fail(
        errors
          .map(
            (error) =>
              error.error ??
              error.msg ??
              error.field_key ??
              "Invalid structured value",
          )
          .join("; "),
      );
    }
  } catch {
    return fail(
      `Malformed ${type} records; provide the complete structured request fields`,
    );
  }
  // Core definitions and plugin validators own their payload shapes; the
  // response union only enumerates compile-time core types.
  return { ok: true, value: { type, value: data } as ResponseValue };
}
import assert from "node:assert/strict";
import { test } from "node:test";

import { createStore } from "jotai";
import { JSDOM } from "jsdom";
import { act, createElement } from "react";
import { createRoot } from "react-dom/client";

import {
  errorsAtom,
  initializeResponses,
  responsesAtom,
} from "@/components/QuestionnaireV2/form/engine/store";

import type { FillFormEntry } from "./formSession";
import type { FillSubject } from "./subject";
import { useFillActions } from "./useFillActions";

test("registered Scribe writes respect the current freeze and recover after saving", async () => {
  const dom = new JSDOM("<!doctype html><div id='root'></div>");
  const globals = {
    window: dom.window,
    document: dom.window.document,
    IS_REACT_ACT_ENVIRONMENT: true,
  };
  const previousGlobals = new Map(
    Object.keys(globals).map((key) => [
      key,
      Object.getOwnPropertyDescriptor(globalThis, key),
    ]),
  );
  for (const [key, value] of Object.entries(globals)) {
    Object.defineProperty(globalThis, key, { value, configurable: true });
  }

  const forms: FillFormEntry[] = [
    {
      key: "form",
      isPrimary: true,
      questionnaire: {
        id: "form",
        slug: "form",
        title: "Clinical note",
        version: "1",
        status: "active",
        subject_type: "encounter",
        questions: [
          { id: "note", link_id: "note", text: "Note", type: "string" },
        ],
      },
    },
  ];
  const subject: FillSubject = {
    type: "encounter",
    patientId: "patient",
    encounterId: "encounter",
    facilityId: "facility",
  };
  const store = createStore();
  store.set(
    responsesAtom,
    initializeResponses(forms[0].questionnaire.questions),
  );
  const getStore = () => store;
  let actions: ReturnType<typeof useFillActions> | undefined;
  function Harness({ frozen }: { frozen: boolean }) {
    actions = useFillActions({ subject, forms, getStore, frozen });
    return null;
  }

  const root = createRoot(dom.window.document.getElementById("root")!);
  try {
    await act(async () =>
      root.render(createElement(Harness, { frozen: false })),
    );
    assert.ok(actions);
    // A plugin may hold this callback while its transcription is pending.
    const invoke = actions.invoke;
    assert.deepEqual(
      await invoke("questionnaire.response.set", {
        link_id: "note",
        values: ["Captured before save"],
      }),
      { ok: true },
    );
    const responsesBeforeSave = store.get(responsesAtom);
    const errorsBeforeSave = [
      { question_id: "note", error: "Keep this error" },
    ];
    store.set(errorsAtom, errorsBeforeSave);

    await act(async () =>
      root.render(createElement(Harness, { frozen: true })),
    );
    const rejected = await invoke("questionnaire.response.set", {
      link_id: "note",
      values: ["Late transcription"],
      note: "Late annotation",
    });
    assert.equal(rejected.ok, false);
    assert.equal(store.get(responsesAtom), responsesBeforeSave);
    assert.equal(store.get(errorsAtom), errorsBeforeSave);
    assert.equal((await invoke("questionnaire.forms.list", {})).ok, true);

    // A failed save restores editing without requiring the plugin to obtain
    // a new callback or remount its session.
    await act(async () =>
      root.render(createElement(Harness, { frozen: false })),
    );
    assert.deepEqual(
      await invoke("questionnaire.response.set", {
        link_id: "note",
        values: ["Corrected after failure"],
      }),
      { ok: true },
    );
    assert.equal(
      store.get(responsesAtom).note.values[0].value,
      "Corrected after failure",
    );
    assert.deepEqual(store.get(errorsAtom), []);
  } finally {
    await act(async () => root.unmount());
    dom.window.close();
    for (const [key, descriptor] of previousGlobals) {
      if (descriptor) Object.defineProperty(globalThis, key, descriptor);
      else Reflect.deleteProperty(globalThis, key);
    }
  }
});
import assert from "node:assert/strict";
import { describe, it } from "node:test";

import type { ResolvedStructuredType } from "@/components/QuestionnaireV2/structured/registry";
import type {
  QuestionnaireResponse,
  ResponseValue,
} from "@/types/questionnaire/form";
import type { Question } from "@/types/questionnaire/question";

import { coerceStructuredFillValue } from "./structuredFillValue";
import { structuredRecordSchemas } from "./structuredRecordSchema";
import type { FillSubject } from "./subject";

const subject: FillSubject = {
  type: "encounter",
  patientId: "patient-1",
  encounterId: "encounter-1",
  facilityId: "facility-1",
};

const code = {
  code: "386661006",
  system: "http://snomed.info/sct",
  display: "Fever",
};
const structuredRows = {
  allergy_intolerance: {
    code,
    clinical_status: "active",
    verification_status: "confirmed",
    category: "food",
    criticality: "low",
  },
  medication_statement: {
    medication: code,
    status: "active",
    information_source: "patient",
    dosage_text: "Once daily",
  },
  medication_request: {
    medication: code,
    dosage_instruction: [],
    authored_on: "2026-09-08",
    do_not_perform: false,
    requester: { id: "clinician" },
  },
  encounter: {
    status: "in_progress",
    priority: "routine",
    period: { start: "2026-09-08T10:00:00Z" },
  },
  appointment: { slot_id: "slot" },
  charge_item: { charge_item_definition: "consultation", quantity: "1" },
  service_request: {
    activity_definition: "blood-count",
    service_request: {
      title: "Blood count",
      code,
      status: "active",
      intent: "order",
      priority: "routine",
      category: "laboratory",
      do_not_perform: false,
      locations: [],
      requester: { id: "clinician" },
    },
  },
};

function clinicalRecord(
  overrides: Record<string, unknown> = {},
): Record<string, unknown> {
  return {
    code: {
      code: "386661006",
      system: "http://snomed.info/sct",
      display: "Fever",
    },
    clinical_status: "active",
    verification_status: "confirmed",
    severity: "moderate",
    category: "encounter_diagnosis",
    ...overrides,
  };
}

function coerce(
  type: NonNullable<Question["structured_type"]>,
  values: unknown[],
  currentRows: unknown[] = [],
  overrides: Partial<ResolvedStructuredType> = {},
) {
  const question: Question = {
    id: "question",
    link_id: "question",
    text: "Clinical data",
    type: "structured",
    structured_type: type,
    required: true,
  };
  const current: QuestionnaireResponse = {
    question_id: question.id,
    link_id: question.link_id,
    structured_type: type,
    values: [{ type, value: currentRows } as ResponseValue],
  };
  const definition = {
    type,
    component: () => null,
    requires: [],
    subjects: ["encounter"],
    draftPolicy: "serialize",
    source: "core",
    persistence: "batch",
    buildRequests: async () => [],
    ...overrides,
  } as ResolvedStructuredType;
  return coerceStructuredFillValue(
    question,
    values,
    current,
    definition,
    subject,
  );
}

describe("structured fill values", () => {
  it("preserves clinical fields, binds context, and marks diagnoses for submission", () => {
    const row = clinicalRecord({
      note: "Persistent fever",
      encounter: "other",
      dirty: false,
    });
    const result = coerce("diagnosis", [row]);
    assert.equal(result.ok, true);
    if (!result.ok) return;
    assert.deepEqual(result.value, {
      type: "diagnosis",
      value: [{ ...row, encounter: subject.encounterId, dirty: true }],
    });
    assert.equal(row.encounter, "other");
  });

  it("requires valid clinical codes and complete clinical request fields", () => {
    assert.equal(coerce("diagnosis", [{}]).ok, false);
    assert.equal(
      coerce("diagnosis", [clinicalRecord({ code: { code: "fever" } })]).ok,
      false,
    );
    assert.equal(
      coerce("symptom", [clinicalRecord({ severity: null })]).ok,
      false,
    );
    assert.equal(
      coerce("diagnosis", [clinicalRecord({ clinical_status: "unknown" })]).ok,
      false,
    );
  });

  it("rejects malformed optional clinical fields and accepts date-only onset values", () => {
    for (const type of ["diagnosis", "symptom"] as const) {
      for (const fields of [
        { note: 123 },
        { onset: "yesterday" },
        { onset: { onset_datetime: 123 } },
        { onset: { onset_age: 12 } },
        { onset: { onset_string: false } },
        { onset: { note: [] } },
        { recorded_date: 123 },
      ]) {
        assert.equal(coerce(type, [clinicalRecord(fields)]).ok, false);
      }
      assert.equal(
        coerce(type, [
          clinicalRecord({
            note: null,
            onset: { onset_datetime: "2026-09-08" },
            recorded_date: "2026-09-08",
          }),
        ]).ok,
        true,
      );
    }
  });

  it("rejects duplicate diagnosis and symptom codes in one write or current values", () => {
    for (const type of ["diagnosis", "symptom"] as const) {
      assert.equal(
        coerce(type, [clinicalRecord(), clinicalRecord()]).ok,
        false,
      );
      assert.equal(
        coerce(type, [clinicalRecord()], [clinicalRecord({ id: "saved" })]).ok,
        false,
      );
      assert.equal(
        coerce(
          type,
          [clinicalRecord({ id: "saved", severity: "severe" })],
          [clinicalRecord({ id: "saved" })],
        ).ok,
        true,
      );
      assert.equal(
        coerce(
          type,
          [clinicalRecord()],
          [
            clinicalRecord({
              id: "saved",
              verification_status: "entered_in_error",
            }),
          ],
        ).ok,
        true,
      );
    }
  });

  it("allows a replacement after an entered-in-error row inside the submitted array", () => {
    assert.equal(
      coerce("diagnosis", [
        clinicalRecord({ verification_status: "entered_in_error" }),
        clinicalRecord(),
      ]).ok,
      true,
    );
  });

  it("retains unsaved rows while adding new rows and accepts repeating the same full replacement", () => {
    for (const type of ["diagnosis", "symptom"] as const) {
      const first = clinicalRecord();
      const second = clinicalRecord({
        code: {
          code: "49727002",
          system: "http://snomed.info/sct",
          display: "Cough",
        },
      });
      assert.equal(coerce(type, [first]).ok, true);
      assert.equal(coerce(type, [first, second], [first]).ok, true);
      assert.equal(coerce(type, [first, second], [first, second]).ok, true);
    }
  });

  it("uses the proposed status when replacing a saved row marked in error", () => {
    const saved = clinicalRecord({ id: "saved" });
    assert.equal(
      coerce(
        "diagnosis",
        [
          clinicalRecord(),
          { ...saved, verification_status: "entered_in_error" },
        ],
        [saved],
      ).ok,
      true,
    );
  });

  it("runs existing validators with the normalized rows, question id, and required flag", () => {
    const medication = { ...structuredRows.medication_request, dirty: false };
    const result = coerce("medication_request", [medication], [], {
      validate: (data, questionId, required) => {
        assert.deepEqual(data, [
          { ...medication, dirty: true, encounter: subject.encounterId },
        ]);
        assert.equal(questionId, "question");
        assert.equal(required, true);
        return [{ question_id: questionId, error: "Dosage is required" }];
      },
    });
    assert.deepEqual(result, { ok: false, error: "Dosage is required" });
    assert.equal(
      coerce("medication_request", [medication], [], {
        validate: () => {
          throw new TypeError("Missing dosage");
        },
      }).ok,
      false,
    );
  });

  it("binds service requests and charge items to the current patient and encounter", () => {
    const service = coerce("service_request", [
      {
        ...structuredRows.service_request,
        encounter: "other",
        service_request: {
          ...structuredRows.service_request.service_request,
          patient: "other",
          encounter: "other",
        },
      },
    ]);
    assert.equal(service.ok, true);
    if (service.ok)
      assert.deepEqual(service.value.value, [
        {
          ...structuredRows.service_request,
          encounter: subject.encounterId,
          service_request: {
            ...structuredRows.service_request.service_request,
            patient: subject.patientId,
            encounter: subject.encounterId,
          },
        },
      ]);
    const charge = coerce("charge_item", [
      { ...structuredRows.charge_item, patient: "other", encounter: "other" },
    ]);
    assert.equal(charge.ok, true);
    if (charge.ok)
      assert.deepEqual(charge.value.value, [
        {
          ...structuredRows.charge_item,
          patient: subject.patientId,
          encounter: subject.encounterId,
        },
      ]);
  });

  it("rejects empty core records and preserves complete records with display fields", () => {
    assert.deepEqual(
      Object.keys(structuredRows).sort(),
      Object.keys(structuredRecordSchemas).sort(),
    );
    for (const type of Object.keys(
      structuredRows,
    ) as (keyof typeof structuredRows)[]) {
      assert.equal(coerce(type, [{}]).ok, false, type);
      const result = coerce(type, [
        { ...structuredRows[type], display_label: "Retained detail" },
      ]);
      assert.equal(result.ok, true, type);
      if (!result.ok) continue;
      const row = (result.value.value as Record<string, unknown>[])[0];
      assert.equal(row.display_label, "Retained detail", type);
    }
  });

  it("accepts one zoned time of death and rejects date-only, invalid calendar dates, or multiple records", () => {
    assert.equal(
      coerce("time_of_death", ["2026-09-08T10:30:00+05:30"]).ok,
      true,
    );
    for (const value of [
      "2026-09-08",
      "10:30",
      "2026-02-30T10:30:00Z",
      "2026-09-08T10:30:00",
    ]) {
      assert.equal(coerce("time_of_death", [value]).ok, false, value);
    }
    assert.equal(
      coerce("time_of_death", ["2026-09-08T10:30:00Z", "2026-09-08T10:30:00Z"])
        .ok,
      false,
    );
  });

  it("rejects file payloads, invalid object rows, and multiple singleton records", () => {
    assert.equal(coerce("files", []).ok, false);
    assert.equal(
      coerce("demo.custom", [{}], [], { draftPolicy: "exclude" }).ok,
      false,
    );
    assert.equal(coerce("diagnosis", ["Fever"]).ok, false);
    assert.equal(coerce("encounter", [{}, {}]).ok, false);
    assert.equal(coerce("appointment", [{}, {}]).ok, false);
    assert.equal(coerce("demo.custom", [{ answer: "value" }]).ok, true);
  });
});

