      false,
    );
    assert.equal(
      coerce("symptom", [clinicalRecord({ severity: null })]).ok,
      false,
    );
    assert.equal(
      coerce("diagnosis", [clinicalRecord({ clinical_status: "unknown" })]).ok,
      false,
    );
  });

