function temporalForm(type: "date" | "dateTime" | "time") {
  const question: Question = {
    id: "temporal",
    link_id: "temporal",
    text: "Recorded at",
    type,
    repeats: true,
  };
  const forms: FillFormEntry[] = [
    {
