  ]) {
    assert.equal(
      (await fill(["2026-09-09", invalid])).ok,
      false,
      String(invalid),
    );
    assert.equal(store.get(responsesAtom), responses);
    assert.equal(store.get(errorsAtom), errors);
  }
});

