      if (replacements.has(index)) {
        return { ok: false, error: `Duplicate ${type} code "${codeOf(row)}"` };
      }
      const previous = existing[index] as Record<string, unknown>;
      replacements.set(index, {
        ...row,
        ...(typeof previous.id === "string" && previous.id
          ? { id: previous.id }
